  def __post_init__(self):
    object.__setattr__(
        self, "basis_directions",
        sorted(self.basis_directions))

  def basis(self) -> Sequence[BasisDirection]:
    return self.basis_directions

  @property
  def num_dims(self) -> int:
    return len(self.basis_directions)

  def null_vector(self, shape: Sequence[int] = ()) -> VectorInBasis:
    magnitudes = np.zeros(shape + (self.num_dims,))
    return VectorInBasis(self.basis_directions, magnitudes)

  def vector_from_basis_direction(
      self,
      direction: BasisDirection,
      magnitude: float = 1.0,
      shape: Sequence[int] = (),
  ) -> VectorInBasis:
    magnitudes = np.zeros(shape + (self.num_dims,))
    idx = list(self.basis_directions).index(direction)
    # Use indexing to support arbitrary shape.
    idx_tuple = (slice(None),) * len(shape) + (idx,)
    magnitudes[idx_tuple] = magnitude
    return VectorInBasis(self.basis_directions, magnitudes)

  def make_vector(
      self,
      magnitudes_dict: dict[BasisDirection, np.ndarray | float],
      shape: Sequence[int] = (),
  ) -> VectorInBasis:
    vec = self.null_vector(shape=shape)
    for direction, magnitude in magnitudes_dict.items():
      vec = vec + self.vector_from_basis_direction(
          direction, magnitude, shape=shape)
    return vec

  def __getitem__(self, key: Iterable[BasisDirection]) -> "VectorSpaceWithBasis":
    return VectorSpaceWithBasis([d for d in self.basis_directions if d in key])

