    object.__setattr__(self, "basis",
                       sorted(self.basis))
    object.__setattr__(self, "num_dims", len(self.basis))
    object.__setattr__(self, "_index_by_direction",
                       {d: i for i, d in enumerate(self.basis)})

  num_dims: int = 0
  _index_by_direction: dict = dataclasses.field(default_factory=dict)

