    return VectorInBasis(self.basis, np.zeros(self.num_dims))

  def vector_from_values(
      self, values: dict[BasisDirection, float]
  ) -> VectorInBasis:
    magnitudes = np.zeros(self.num_dims)
    for direction, value in values.items():
      magnitudes[self._index_by_direction[direction]] = value
    return VectorInBasis(self.basis, magnitudes)

  def make_vector(self, magnitudes: np.ndarray) -> VectorInBasis:
    return VectorInBasis(self.basis, magnitudes)

  def __contains__(self, direction: BasisDirection) -> bool:
    return direction in self._index_by_direction


