    self.input_key = input_key
    self.outputs = {}
    self.trunk(*args, **kwargs)
    outputs = copy.copy(self.outputs)
    self.outputs = {}
    self.input_key = None
    return outputs

def _get_trunk_fields(self, sample: Mapping):
    if self.input_key in self.trunk_field_args:
        args_keys = self.trunk_field_args[self.input_key]
        kwargs_keys = self.trunk_field_kwargs[self.input_key]
    elif None in self.trunk_field_args:
        args_keys = self.trunk_field_args[None]
        kwargs_keys = self.trunk_field_kwargs[None]
    else:
        raise KeyError(
            f"No trunk_fields specified for input_key: {self.input_key}"
        )
    args = [sample[k] for k in args_keys]
    kwargs = {k: sample[v] for k, v in kwargs_keys.items()}
    return args, kwargs

def forward(self, sample: Dict) -> Dict:
    self.outputs = {}
    # VisionSample has input_key attr, dict sample has "input_key" key
    if isinstance(sample, Mapping):
        self.input_key = sample.get("input_key", None)
    else:
        self.input_key = getattr(sample, "input_key", None)
    args, kwargs = self._get_trunk_fields(sample)
    if self.handle_list_inputs:
        # hack: trunk expects list inputs stacked
        if len(args) == 1 and isinstance(args[0], (list, tuple)):
            args = [torch.stack(args[0])]
    self.trunk(*args, **kwargs)
    outputs = self.outputs
    self.outputs = {}
    self.input_key = None
    return outputs

def remove_hooks(self):
    for handle in self.hook_handles:
        handle.remove()
    self.hook_handles = []

