def construct_optimizer(
    model: torch.nn.Module,
    optimizer_cfg: DictConfig,
) -> Tuple[OmniOptimizer, List[Dict[str, Any]]]:
    all_parameter_names = {name for name, _ in model.named_parameters()}
    # Map unix patterns to parameter names
    for option_cfg in optimizer_cfg.options.values():
        for scheduler_cfg in option_cfg.schedulers:
            scheduler_cfg.parameter_names = unix_pattern_to_parameter_names(
                scheduler_cfg, model
            )
    # Set default parameters for each option
    for option_cfg in optimizer_cfg.options.values():
        set_default_parameters(option_cfg.schedulers, all_parameter_names)
    # Cartesian product of scheduler cfgs across options gives param groups
    scheduler_cfgs_per_param_group = itertools.product(
        *[option_cfg.schedulers for option_cfg in optimizer_cfg.options.values()]
    )
    schedulers, param_groups = map_scheduler_cfgs_to_param_groups(
        scheduler_cfgs_per_param_group, model
    )
    validate_param_group_params(param_groups, model)
    optimizer = hydra.utils.instantiate(optimizer_cfg.optimizer, params=param_groups)
    return optimizer, schedulers

