def interpolate_outliers(x: jnp.ndarray,
                         outlier_idx: jnp.ndarray) -> jnp.ndarray:
  """Overwrites outliers in x with interpolated values.

  Args:
    x: The original univariate variable with outliers.
    outlier_idx: Indices of outliers.

  Returns:
    Variable with outliers interpolated.
  """
  x_clean = np.array(x, dtype=float)
  n = len(x_clean)
  outlier_set = set(np.asarray(outlier_idx).tolist())
  for idx in sorted(outlier_set):
    prev_idx = idx - 1
    while prev_idx in outlier_set and prev_idx >= 0:
      prev_idx -= 1
    next_idx = idx + 1
    while next_idx in outlier_set and next_idx < n:
      next_idx += 1
    if prev_idx >= 0 and next_idx < n:
      x_clean[idx] = (x_clean[prev_idx] + x_clean[next_idx]) / 2.0
    elif prev_idx >= 0:
      x_clean[idx] = x_clean[prev_idx]
    elif next_idx < n:
      x_clean[idx] = x_clean[next_idx]
  return jnp.array(x_clean)

