def _evaluate_tokens(self, expr: Tokens,
                     xs: Sequence[Value]) -> Sequence[Value]:
  return list(xs)

def _evaluate_indices(self, expr: Indices,
                      xs: Sequence[Value]) -> Sequence[int]:
  return list(range(len(xs)))

def _evaluate_length(self, expr: Length,
                     xs: Sequence[Value]) -> Sequence[int]:
  return [len(xs)] * len(xs)

def _evaluate_select(
    self, expr: Select, xs: Sequence[Value]
) -> SelectorValue:
  keys = self.evaluate(expr.keys, xs)
  queries = self.evaluate(expr.queries, xs)
  assert isinstance(keys, list)
  assert isinstance(queries, list)
  return [
      [bool(expr.predicate(k, q)) for k in keys] for q in queries
  ]

def _evaluate_selector_and(
    self, expr: SelectorAnd, xs: Sequence[Value]
) -> SelectorValue:
  fst = self.evaluate(expr.fst, xs)
  snd = self.evaluate(expr.snd, xs)
  assert isinstance(fst, list)
  assert isinstance(snd, list)
  return [
      [a and b for a, b in zip(fst_row, snd_row)]
      for fst_row, snd_row in zip(fst, snd)
  ]

def _evaluate_selector_or(
    self, expr: SelectorOr, xs: Sequence[Value]
) -> SelectorValue:
  fst = self.evaluate(expr.fst, xs)
  snd = self.evaluate(expr.snd, xs)
  assert isinstance(fst, list)
  assert isinstance(snd, list)
  return [
      [a or b for a, b in zip(fst_row, snd_row)]
      for fst_row, snd_row in zip(fst, snd)
  ]

def _evaluate_selector_not(
    self, expr: SelectorNot, xs: Sequence[Value]
) -> SelectorValue:
  inner = self.evaluate(expr.inner, xs)
  assert isinstance(inner, list)
  return [[not v for v in row] for row in inner]

def _evaluate_constant_selector(
    self, expr: ConstantSelector, xs: Sequence[Value]
) -> SelectorValue:
  n = len(xs)
  return [[expr.value] * n for _ in range(n)]

def _evaluate_aggregate(
    self, expr: Aggregate, xs: Sequence[Value]
) -> Sequence[Value]:
  selector = self.evaluate(expr.selector, xs)
  sop = self.evaluate(expr.sop, xs)
  assert isinstance(selector, list)
  assert isinstance(sop, list)
  out = []
  for row in selector:
    selected = [v for v, s in zip(sop, row) if s]
    if selected:
      out.append(sum(selected) / len(selected))
    else:
      if expr.default is None:
        raise ValueError("No values selected and no default provided.")
      out.append(expr.default)
  return out

def _evaluate_sequence_map(
    self, expr: SequenceMap, xs: Sequence[Value]
) -> Sequence[Value]:
  children_values = [self.evaluate(child, xs) for child in expr.children]
