  assert isinstance(keys, list)
  assert isinstance(queries, list)
  return [
      [
          bool(selector.predicate(k, q)) if None not in [k, q] else False
          for k in keys
      ]
      for q in queries
  ]

def eval_selector_and(self, selector: SelectorAnd,
                      xs: Sequence[Value]) -> SelectorValue:
  fst_value = self.evaluate(selector.fst, xs)
  snd_value = self.evaluate(selector.snd, xs)
  assert isinstance(fst_value, list)
  assert isinstance(snd_value, list)
  return [
      [a and b for a, b in zip(fst_row, snd_row)]
      for fst_row, snd_row in zip(fst_value, snd_value)
  ]

def eval_selector_or(self, selector: SelectorOr,
                     xs: Sequence[Value]) -> SelectorValue:
  fst_value = self.evaluate(selector.fst, xs)
  snd_value = self.evaluate(selector.snd, xs)
  assert isinstance(fst_value, list)
  assert isinstance(snd_value, list)
  return [
      [a or b for a, b in zip(fst_row, snd_row)]
      for fst_row, snd_row in zip(fst_value, snd_value)
  ]

def eval_selector_not(self, selector: SelectorNot,
                      xs: Sequence[Value]) -> SelectorValue:
  inner_value = self.evaluate(selector.inner, xs)
  assert isinstance(inner_value, list)
  return [[not v for v in row] for row in inner_value]

def eval_constant_selector(self, selector: ConstantSelector,
                           xs: Sequence[Value]) -> SelectorValue:
  return [[selector.value] * len(xs) for _ in xs]

