@dataclasses.dataclass(frozen=True)
class VectorSpaceWithBasis:
  """A vector space with a given basis."""

  basis: Sequence[BasisDirection]

  def __post_init__(self):
    object.__setattr__(self, "basis",
                       sorted(self.basis))
    object.__setattr__(self, "num_dims", len(self.basis))

  num_dims: int = 0

  def null_vector(self, shape: Sequence[int] = ()) -> VectorInBasis:
    magnitudes = np.zeros(shape + (self.num_dims,))
    return VectorInBasis(self.basis, magnitudes)

  def vector_from_basis_direction(
      self, direction: BasisDirection) -> VectorInBasis:
    magnitudes = np.zeros((self.num_dims,))
    magnitudes[self.basis.index(direction)] = 1.0
    return VectorInBasis(self.basis, magnitudes)

  def make_vector(
      self,
      magnitudes: Union[np.ndarray, Sequence[float]],
      basis: Optional[Sequence[BasisDirection]] = None,
  ) -> VectorInBasis:
    if basis is None:
      basis = self.basis
    return VectorInBasis(
        list(basis), np.asarray(magnitudes)).project(self)

  def __contains__(self, direction: BasisDirection) -> bool:
    return direction in self.basis

  def __getitem__(self, direction: BasisDirection) -> int:
    return self.basis.index(direction)


def join_vector_spaces(
    spaces: Iterable[VectorSpaceWithBasis]) -> VectorSpaceWithBasis:
  basis = []
  for space in spaces:
    basis.extend(space.basis)
  if len(set(basis)) != len(basis):
    raise ValueError(f"Overlapping bases: {basis}")
  return VectorSpaceWithBasis(basis)


