@dataclasses.dataclass
class SeriesWithResiduals(Block):
  """Applies blocks in series, with residual connections."""
  sub_blocks: List[Block]
  residual_space: Optional[bases.VectorSpaceWithBasis] = None

  def __post_init__(self):
    if self.residual_space is None:
      self.residual_space = bases.join_vector_spaces(
          *[block.residual_space for block in self.sub_blocks])
    for block in self.sub_blocks:
      assert block.residual_space.issubspace(self.residual_space)

  def apply(self, x: bases.VectorInBasis) -> bases.VectorInBasis:
    assert x in self.residual_space
    for block in self.sub_blocks:
      x = x + project(block.residual_space, self.residual_space)(
          block.apply(project(self.residual_space, block.residual_space)(x)))
    return x

  def as_transformer_block(self) -> "SeriesWithResiduals":
    return self

