def forward(self, sample: Mapping[str, VisionSample]) -> Dict[str, torch.Tensor]:
    # sample is a dict with a single key (input_key) mapping to VisionSample
    # or a VisionSample directly?
    if isinstance(sample, Mapping):
        assert len(sample) == 1, "Expected sample dict with single key"
        self.input_key = list(sample.keys())[0]
        sample_val = sample[self.input_key]
    else:
        # assume sample already has input_key set externally
        sample_val = sample

    args_keys, kwargs_keys = self._get_trunk_fields()

    if isinstance(sample_val, Mapping):
        args = [sample_val[k] for k in args_keys]
        kwargs = {k: sample_val[v] for k, v in kwargs_keys.items()}
    else:
        # VisionSample: fetch attributes
        args = [getattr(sample_val, k) for k in args_keys]
        kwargs = {k: getattr(sample_val, v) for k, v in kwargs_keys.items()}

    if self.handle_list_inputs:
        # hack: trunk expects list inputs
        if len(args) == 1 and isinstance(args[0], list):
            pass
        else:
            pass

    self.outputs = {}
    try:
        self.trunk(*args, **kwargs)
    except Exception:
        self.outputs = {}
        self.input_key = None
        raise
    outputs = self.outputs
    self.outputs = {}
    self.input_key = None
    return outputs

def remove_hooks(self):
    for handle in self.hook_handles:
        handle.remove()
    self.hook_handles = []

    assert isinstance(sub_batch, VisionSample), f"Received {type(sub_batch)}"
    fields_args, fields_kwargs = self._get_trunk_fields()
    sample_args = [getattr(sub_batch, arg) for arg in fields_args]
    sample_kwargs = {
        k: getattr(sub_batch, v) for k, v in fields_kwargs.items()
    }
    self.trunk(*sample_args, *args, **sample_kwargs, **kwargs)

