def _get_trunk_args_kwargs(self, sample, input_key):
    if input_key in self.trunk_field_args:
        args_keys = self.trunk_field_args[input_key]
        kwargs_map = self.trunk_field_kwargs[input_key]
    elif None in self.trunk_field_args:
        args_keys = self.trunk_field_args[None]
        kwargs_map = self.trunk_field_kwargs[None]
    else:
        raise KeyError(f"No trunk_fields specified for input_key: {input_key}")
    if self.handle_list_inputs and isinstance(sample, (list, tuple)):
        args = []
        for k in args_keys:
            args.append([s[k] for s in sample])
        kwargs = {}
        for kw, k in kwargs_map.items():
            kwargs[kw] = [s[k] for s in sample]
    else:
        args = [sample[k] for k in args_keys]
        kwargs = {kw: sample[k] for kw, k in kwargs_map.items()}
    return args, kwargs

def forward(self, sample: Mapping, input_key: Optional[str] = None):
    self.input_key = input_key
    self.outputs = {}
    args, kwargs = self._get_trunk_args_kwargs(sample, input_key)
    self.trunk(*args, **kwargs)
    outputs = self.outputs
    self.outputs = {}
    self.input_key = None
    return outputs

