  return float(jnp.max(jnp.abs(jnp.cumsum(p_prob) - jnp.cumsum(q_prob))))
def _hellinger():
  return float(
      jnp.sqrt(0.5 * jnp.sum((jnp.sqrt(p_prob) - jnp.sqrt(q_prob)) ** 2)))
def _js():
  m = 0.5 * (p_prob + q_prob)
  # Avoid log(0) by masking.
  p_term = jnp.where(p_prob > 0, p_prob * jnp.log(p_prob / m), 0.0)
  q_term = jnp.where(q_prob > 0, q_prob * jnp.log(q_prob / m), 0.0)
  js_div = 0.5 * (jnp.sum(p_term) + jnp.sum(q_term))
  # Normalize to [0, 1] (using log base 2).
  return float(js_div / jnp.log(2.0))
