def accumulate(
    self,
    column: Column,
    into: Column,
    func: Func,
) -> DataFrame:
    return _wrap(accumulate(self._data, column, into, func))

def append(self, other: DataFrame) -> DataFrame:
    return _wrap(append(self._data, other._data))

def combine(self, other: DataFrame) -> DataFrame:
    return _wrap(combine(self._data, other._data))

def compare(self, other: DataFrame) -> DataFrame:
    return _wrap(compare(self._data, other._data))

def concat(self, column: Column, into: Column, sep: str = "") -> DataFrame:
    return _wrap(concat(self._data, column, into, sep))

def dedupe(self, columns: Columns | None = None) -> DataFrame:
    return _wrap(dedupe(self._data, columns))

def drop(self, columns: Columns) -> DataFrame:
    return _wrap(drop(self._data, columns))

def explode(self, column: Column, sep: str) -> DataFrame:
    return _wrap(explode(self._data, column, sep))

def extend(self, other: DataFrame) -> DataFrame:
    return _wrap(extend(self._data, other._data))

def filter(self, func: Func) -> DataFrame:
    return _wrap(filter(self._data, func))

def gather(self, columns: Columns, into: tuple[Column, Column]) -> DataFrame:
    return _wrap(gather(self._data, columns, into))

def group(self, columns: Columns) -> GroupedFrame:
    return _wrap(group(self._data, columns))

def join(self, other: DataFrame, on: Columns, how: str = "inner") -> DataFrame:
    return _wrap(join(self._data, other._data, on, how))

def mutate(self, over: dict[Column, tuple[Column, Func]]) -> DataFrame:
    return _wrap(mutate(self._data, over))

def rename(self, columns: dict[Column, Column]) -> DataFrame:
    return _wrap(rename(self._data, columns))

def sample(self, n: int | None = None, frac: float | None = None, seed: int | None = None) -> DataFrame:
    return _wrap(sample(self._data, n, frac, seed))

def select(self, columns: Columns) -> DataFrame:
    return _wrap(select(self._data, columns))

def sort(self, columns: Columns, descending: bool = False) -> DataFrame:
    return _wrap(sort(self._data, columns, descending))

def spread(self, column: Column, using: Column) -> DataFrame:
    return _wrap(spread(self._data, column, using))

def take(self, n: int) -> DataFrame:
    return _wrap(take(self._data, n))

def unpack(self, column: Column, sep: str) -> DataFrame:
    return _wrap(unpack(self._data, column, sep))
